mapper.select:
SELECT COALESCE(MAX(t.turn_id), 0)
FROM conversation_turn t
JOIN conversation c ON c.id = t.conversation_id
WHERE c.id = #{conversationId}
  AND c.user_id = #{userId}
  AND c.is_deleted = 0

mapper.insert:
INSERT INTO conversation_turn (
    conversation_id, turn_id, type, content, error_message, trace_id,
    agent_key, model_provider_key, model_name, protocol_type
)
SELECT c.id, #{turnId}, #{type}, #{content}, #{errorMessage}, #{traceId},
       #{agentKey}, #{modelProviderKey}, #{modelName}, #{protocolType}
FROM conversation c
WHERE c.id = #{conversationId}
  AND c.user_id = #{userId}
  AND c.is_deleted = 0

